// Audio, Video and Albums installer. Run from the repo root or apps\web:  node install-media.mjs
// Old copies are saved as <name>.bak. en.json / ta.json get new "audio", "video" and "albums" blocks; nothing is removed.
// It uses the photos already in public\images (acharya-*, ashram-*, festival, swamiji). It needs no other installer first.
import fs from 'node:fs';
import path from 'node:path';
let root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const isWeb = (d) => fs.existsSync(path.join(d, 'src', 'dictionaries', 'en.json'));
if (!isWeb(root) && isWeb(path.join(root, 'apps', 'web'))) root = path.join(root, 'apps', 'web');
if (!isWeb(root)) { console.error('Run this from the repo root or apps\\web.'); process.exit(1); }
console.log('Installing into ' + root + '\n');
const FILES = {"src/data/media.ts":"// DUMMY DATA. The CMS portal will replace this file: keep the shape, swap the source.\n// Titles, series and photos below are placeholders taken from the design reference, not the ashram's real archive.\n// Audio: put files in apps/web/public/audio/ and set `src` (for example '/audio/gita-2-1.mp3'). Empty `src` = preview mode.\n// Video: set `youtubeId` (the part after v= in a YouTube address). Empty = \"coming soon\" in the pop-up.\n// Photos: put files in apps/web/public/images/ and set `src`, `w` and `h` (the picture size in pixels).\n\nimport type { L } from './sevas';\n\nexport type SeriesKey = 'gita' | 'thirukkural' | 'thayumanavar' | 'upanishads' | 'kaivalya' | 'events';\n\nexport const SERIES: { key: SeriesKey; name: L }[] = [\n  { key: 'gita', name: { en: 'Bhagavad Gita', ta: 'பகவத் கீதை' } },\n  { key: 'thirukkural', name: { en: 'Thirukkural', ta: 'திருக்குறள்' } },\n  { key: 'thayumanavar', name: { en: 'Thayumanavar', ta: 'தாயுமானவர்' } },\n  { key: 'upanishads', name: { en: 'Upanishads', ta: 'உபநிஷதங்கள்' } },\n  { key: 'kaivalya', name: { en: 'Kaivalya Navaneetham', ta: 'கைவல்ய நவநீதம்' } },\n  { key: 'events', name: { en: 'Events', ta: 'நிகழ்வுகள்' } },\n];\nexport const seriesName = (k: SeriesKey, locale: 'en' | 'ta') => SERIES.find((s) => s.key === k)?.name[locale] ?? '';\n\n// Links from the old website\nexport const YOUTUBE_URL = 'https://www.youtube.com/channel/UCnpgt-vD7stQAllAL5PRjXg/playlists';\nexport const PHOTO_FOLDER_URL = 'https://drive.google.com/drive/folders/1cYFVkTrtUgqylFdkuoYtjmkVWdgTo7oB?usp=drive_link';\n\n// ---------- Audio ----------\nexport type AudioTrack = {\n  id: string;\n  title: L;\n  series: Exclude<SeriesKey, 'events'>;\n  duration: number;   // seconds\n  date: string;       // YYYY-MM-DD\n  src: string;        // '' until the file is uploaded\n};\n\nexport const AUDIO: AudioTrack[] = [\n  { id: 'gita-2-1', series: 'gita', duration: 2710, date: '2026-02-12', src: '',\n    title: { en: 'Bhagavad Gita - Chapter 2 (Sankhya Yoga) - Part 1', ta: 'பகவத் கீதை - அத்தியாயம் 2 (சாங்க்ய யோகம்) - பகுதி 1' } },\n  { id: 'kural-porutpal', series: 'thirukkural', duration: 3160, date: '2026-01-28', src: '',\n    title: { en: 'Thirukkural - Porutpal (Wealth) - Introduction', ta: 'திருக்குறள் - பொருட்பால் - முன்னுரை' } },\n  { id: 'thayumanavar-1', series: 'thayumanavar', duration: 2295, date: '2026-01-15', src: '',\n    title: { en: 'Thayumanavar Padalgal - Anandha Kalippu', ta: 'தாயுமானவர் பாடல்கள் - ஆனந்தக் களிப்பு' } },\n  { id: 'kaivalya-3', series: 'kaivalya', duration: 3750, date: '2025-12-10', src: '',\n    title: { en: 'Kaivalya Navaneetham - Lecture Series 3', ta: 'கைவல்ய நவநீதம் - சொற்பொழிவுத் தொடர் 3' } },\n  { id: 'upanishad-mandukya-4', series: 'upanishads', duration: 2980, date: '2025-11-22', src: '',\n    title: { en: 'Upanishad Sara Sangraham - Lecture 4', ta: 'உபநிஷத சார சங்கிரகம் - சொற்பொழிவு 4' } },\n  { id: 'gita-2-2', series: 'gita', duration: 2840, date: '2025-11-05', src: '',\n    title: { en: 'Bhagavad Gita - Chapter 2 (Sankhya Yoga) - Part 2', ta: 'பகவத் கீதை - அத்தியாயம் 2 (சாங்க்ய யோகம்) - பகுதி 2' } },\n  { id: 'kural-aram', series: 'thirukkural', duration: 2660, date: '2025-10-18', src: '',\n    title: { en: 'Thirukkural - Aram (Virtue) - Introduction', ta: 'திருக்குறள் - அறத்துப்பால் - முன்னுரை' } },\n  { id: 'upanishad-kena-1', series: 'upanishads', duration: 3300, date: '2025-09-30', src: '',\n    title: { en: 'Kena Upanishad - Lecture 1', ta: 'கேனோபநிஷத் - சொற்பொழிவு 1' } },\n];\n\n// ---------- Video ----------\nexport type VideoItem = {\n  id: string;\n  title: L;\n  desc: L;\n  series: SeriesKey;\n  duration: number;   // seconds\n  date: string;\n  youtubeId: string;  // '' until the video is chosen\n  thumb: string;      // picture in /public/images\n  featured?: boolean;\n};\n\nexport const VIDEOS: VideoItem[] = [\n  { id: 'sadhana-panchakam', series: 'upanishads', duration: 3120, date: '2026-03-02', youtubeId: '', thumb: '/images/ashram-patashala.jpg', featured: true,\n    title: { en: 'Sadhana Panchakam of Adi Sankara', ta: 'ஆதி சங்கரரின் சாதனா பஞ்சகம்' },\n    desc: { en: 'Step-by-step guidance on spiritual practice from a classical text.', ta: 'பாரம்பரிய நூலிலிருந்து ஆன்மிகப் பயிற்சிக்கான படிப்படியான வழிகாட்டல்.' } },\n  { id: 'kural-essence', series: 'thirukkural', duration: 2540, date: '2026-02-14', youtubeId: '', thumb: '/images/festival.jpg',\n    title: { en: 'Thirukkural Vedanta Essence', ta: 'திருக்குறள் வேதாந்தச் சாரம்' },\n    desc: { en: 'Exploring the deep spiritual dimensions of classical Tamil ethics.', ta: 'செம்மொழித் தமிழ் அறநூலின் ஆழ்ந்த ஆன்மிகப் பரிமாணங்கள்.' } },\n  { id: 'mind-meditation', series: 'upanishads', duration: 2210, date: '2026-01-20', youtubeId: '', thumb: '/images/ashram-vidyapitham.jpg',\n    title: { en: 'Mind Control & Meditation', ta: 'மனக்கட்டுப்பாடும் தியானமும்' },\n    desc: { en: 'Practical teachings on mental discipline according to Yoga Sutras.', ta: 'யோக சூத்திரங்களின்படி மன ஒழுக்கம் குறித்த நடைமுறை உபதேசங்கள்.' } },\n  { id: 'gita-chapter-2', series: 'gita', duration: 3380, date: '2025-12-28', youtubeId: '', thumb: '/images/ashram-classroom.jpg',\n    title: { en: 'Bhagavad Gita - Chapter 2 Overview', ta: 'பகவத் கீதை - அத்தியாயம் 2 அறிமுகம்' },\n    desc: { en: 'An overview of the second chapter and its central teaching.', ta: 'இரண்டாம் அத்தியாயத்தின் அறிமுகமும் அதன் மையக் கருத்தும்.' } },\n  { id: 'thayumanavar-padal', series: 'thayumanavar', duration: 1980, date: '2025-12-02', youtubeId: '', thumb: '/images/ashram-river.jpg',\n    title: { en: 'Thayumanavar Padalgal - Selected Verses', ta: 'தாயுமானவர் பாடல்கள் - தேர்ந்தெடுத்தவை' },\n    desc: { en: 'Reflections on selected verses of Thayumanavar.', ta: 'தாயுமானவரின் தேர்ந்தெடுத்த பாடல்கள் பற்றிய சிந்தனைகள்.' } },\n  { id: 'guru-puja-event', series: 'events', duration: 1760, date: '2025-10-12', youtubeId: '', thumb: '/images/ashram-vilasa.jpg',\n    title: { en: 'Guru Puja Aradhana', ta: 'குரு பூஜை ஆராதனை' },\n    desc: { en: 'Highlights of the Guru Puja at the ashram.', ta: 'ஆசிரமத்தில் நடைபெற்ற குரு பூஜையின் சிறப்புக் காட்சிகள்.' } },\n  { id: 'kaivalya-intro', series: 'kaivalya', duration: 2890, date: '2025-09-14', youtubeId: '', thumb: '/images/ashram-dining.jpg',\n    title: { en: 'Kaivalya Navaneetham - Introduction', ta: 'கைவல்ய நவநீதம் - அறிமுகம்' },\n    desc: { en: 'An introduction to the text and how to study it.', ta: 'நூலின் அறிமுகமும் அதைப் படிக்கும் முறையும்.' } },\n  { id: 'upanishad-sara', series: 'upanishads', duration: 3015, date: '2025-08-30', youtubeId: '', thumb: '/images/acharya-1.jpg',\n    title: { en: 'Upanishad Sara Sangraham - Lecture 4', ta: 'உபநிஷத சார சங்கிரகம் - சொற்பொழிவு 4' },\n    desc: { en: 'The fourth lecture of the Upanishad Sara Sangraham series.', ta: 'உபநிஷத சார சங்கிரகத் தொடரின் நான்காம் சொற்பொழிவு.' } },\n];\n\n// ---------- Albums ----------\nexport type AlbumKey = 'swamiji' | 'ashramam' | 'festivals' | 'river';\nexport const ALBUMS: { key: AlbumKey; name: L }[] = [\n  { key: 'swamiji', name: { en: 'Swamiji', ta: 'ஸ்வாமிஜி' } },\n  { key: 'ashramam', name: { en: 'Ashramam', ta: 'ஆசிரமம்' } },\n  { key: 'festivals', name: { en: 'Festivals & Pujas', ta: 'விழாக்களும் பூஜைகளும்' } },\n  { key: 'river', name: { en: 'Pennai River', ta: 'பெண்ணை ஆறு' } },\n];\n\nexport type Photo = { id: string; title: L; album: AlbumKey; src: string; w: number; h: number };\n\nexport const PHOTOS: Photo[] = [\n  { id: 'p-swamiji', album: 'swamiji', src: '/images/swamiji.jpg', w: 690, h: 972, title: { en: 'Pujyasri Swami Omkarananda', ta: 'பூஜ்யஸ்ரீ ஸ்வாமி ஓங்காரானந்தர்' } },\n  { id: 'p-guru-puja', album: 'festivals', src: '/images/festival.jpg', w: 959, h: 716, title: { en: 'Guru Puja Aradhana', ta: 'குரு பூஜை ஆராதனை' } },\n  { id: 'p-river', album: 'river', src: '/images/ashram-river.jpg', w: 959, h: 716, title: { en: 'Pennai Riverbanks', ta: 'பெண்ணை ஆற்றங்கரை' } },\n  { id: 'p-vidyapitham', album: 'ashramam', src: '/images/ashram-vidyapitham.jpg', w: 959, h: 716, title: { en: 'Vidyapitham', ta: 'வித்யாபீடம்' } },\n  { id: 'p-acharya-1', album: 'swamiji', src: '/images/acharya-1.jpg', w: 778, h: 433, title: { en: 'Acharya', ta: 'ஆசார்யர்' } },\n  { id: 'p-ghosala', album: 'ashramam', src: '/images/ashram-ghosala.jpg', w: 959, h: 716, title: { en: 'Go Shala', ta: 'கோசாலை' } },\n  { id: 'p-patashala', album: 'ashramam', src: '/images/ashram-patashala.jpg', w: 959, h: 716, title: { en: 'Pathashala', ta: 'பாடசாலை' } },\n  { id: 'p-vilasa', album: 'festivals', src: '/images/ashram-vilasa.jpg', w: 959, h: 716, title: { en: 'Ashram Gathering', ta: 'ஆசிரமக் கூடுகை' } },\n  { id: 'p-acharya-2', album: 'swamiji', src: '/images/acharya-2.jpg', w: 805, h: 433, title: { en: 'Acharya in discourse', ta: 'சொற்பொழிவில் ஆசார்யர்' } },\n  { id: 'p-classroom', album: 'ashramam', src: '/images/ashram-classroom.jpg', w: 959, h: 716, title: { en: 'Classroom', ta: 'வகுப்பறை' } },\n  { id: 'p-dining', album: 'ashramam', src: '/images/ashram-dining.jpg', w: 959, h: 716, title: { en: 'Annadhanam Hall', ta: 'அன்னதான மண்டபம்' } },\n  { id: 'p-acharya-3', album: 'swamiji', src: '/images/acharya-3.jpg', w: 804, h: 433, title: { en: 'Acharya with devotees', ta: 'பக்தர்களுடன் ஆசார்யர்' } },\n];\n\n// ---------- helpers ----------\n// 2710 -> \"45:10\", 3750 -> \"1:02:30\"\nexport function clock(s: number) {\n  if (!Number.isFinite(s) || s < 0) return '0:00';\n  const h = Math.floor(s / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  const sec = Math.floor(s % 60);\n  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}` : `${m}:${String(sec).padStart(2, '0')}`;\n}\n","src/components/media/MediaHero.tsx":"import Link from 'next/link';\n\ntype Stat = { value: string; label: string };\n\nfunction Mandala({ className = '' }: { className?: string }) {\n  return (\n    <svg aria-hidden=\"true\" viewBox=\"0 0 200 200\" className={className} fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.2\">\n      {[0, 30, 60, 90, 120, 150].map((d) => (\n        <ellipse key={d} cx=\"100\" cy=\"100\" rx=\"22\" ry=\"80\" transform={`rotate(${d} 100 100)`} />\n      ))}\n      <circle cx=\"100\" cy=\"100\" r=\"80\" />\n      <circle cx=\"100\" cy=\"100\" r=\"30\" />\n    </svg>\n  );\n}\n\nconst ICONS = {\n  audio: <path d=\"M4 14v-2a8 8 0 0 1 16 0v2M4 14h3v6H4zM17 14h3v6h-3z\" />,\n  video: <><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\" /><path d=\"M10 9.5v5l4.5-2.5z\" fill=\"currentColor\" /></>,\n  album: <><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\" /><circle cx=\"9\" cy=\"10\" r=\"1.7\" /><path d=\"M21 16l-5-5-8 8\" /></>,\n};\n\n// Title band for the Audio, Video and Albums pages: maroon with a mandala, a glowing icon, and a few numbers\nexport default function MediaHero({\n  kind,\n  home,\n  homeHref,\n  current,\n  crumbLabel,\n  eyebrow,\n  title,\n  intro,\n  stats,\n}: {\n  kind: keyof typeof ICONS;\n  home: string;\n  homeHref: string;\n  current: string;\n  crumbLabel: string;\n  eyebrow: string;\n  title: string;\n  intro: string;\n  stats: Stat[];\n}) {\n  return (\n    <section aria-labelledby=\"media-title\" className=\"relative isolate overflow-hidden bg-gradient-to-br from-maroon via-maroon to-charcoal text-white\">\n      <Mandala className=\"absolute -right-28 -top-28 -z-10 h-[34rem] w-[34rem] text-white/10\" />\n      <Mandala className=\"absolute -bottom-40 -left-24 -z-10 h-80 w-80 text-saffron/20\" />\n\n      <nav aria-label={crumbLabel} className=\"mx-auto max-w-7xl px-4 pt-6 text-sm text-white/80 lg:px-8\">\n        <ol className=\"flex flex-wrap items-center gap-2\">\n          <li><Link href={homeHref} className=\"underline-offset-4 hover:text-white hover:underline\">{home}</Link></li>\n          <li aria-hidden=\"true\">/</li>\n          <li aria-current=\"page\" className=\"font-semibold text-white\">{current}</li>\n        </ol>\n      </nav>\n\n      <div className=\"mx-auto flex max-w-7xl flex-col gap-8 px-4 pb-20 pt-8 sm:pb-24 lg:flex-row lg:items-end lg:justify-between lg:px-8\">\n        <div className=\"max-w-2xl\">\n          <span aria-hidden=\"true\" className=\"inline-flex h-16 w-16 items-center justify-center rounded-full bg-saffron/20 text-saffron ring-1 ring-saffron/60\" style={{ boxShadow: '0 0 40px rgba(217,119,6,0.45)' }}>\n            <svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\">{ICONS[kind]}</svg>\n          </span>\n          <p className=\"mt-5 text-sm font-bold uppercase tracking-[0.2em] text-saffron [html[lang='ta']_&]:tracking-normal\">{eyebrow}</p>\n          <h1 id=\"media-title\" className=\"animate-fade-up mt-2 font-display text-5xl font-semibold leading-[1.1] !text-white motion-reduce:animate-none sm:text-6xl lg:text-7xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-4xl [html[lang='ta']_&]:sm:text-5xl [html[lang='ta']_&]:lg:text-6xl\">{title}</h1>\n          <div aria-hidden=\"true\" className=\"mt-4 flex items-center gap-3\"><span className=\"h-px w-14 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-14 bg-saffron\" /></div>\n          <p className=\"mt-5 font-serif text-lg leading-relaxed text-white/90 sm:text-xl\">{intro}</p>\n        </div>\n\n        <dl className=\"grid grid-cols-3 gap-3 sm:gap-4 lg:w-[26rem]\">\n          {stats.map((s) => (\n            <div key={s.label} className=\"rounded-xl border border-white/20 bg-white/10 px-3 py-4 text-center backdrop-blur-sm\">\n              <dd className=\"font-display text-3xl font-semibold leading-none text-white sm:text-4xl\">{s.value}</dd>\n              <dt className=\"mt-2 text-xs font-semibold uppercase tracking-wider text-white/80 [html[lang='ta']_&]:tracking-normal\">{s.label}</dt>\n            </div>\n          ))}\n        </dl>\n      </div>\n\n      <svg aria-hidden=\"true\" viewBox=\"0 0 1440 40\" preserveAspectRatio=\"none\" className=\"absolute inset-x-0 bottom-0 h-8 w-full text-white sm:h-10\">\n        <path d=\"M0 40V18C240 -2 480 -2 720 14S1200 34 1440 12V40Z\" fill=\"currentColor\" />\n      </svg>\n    </section>\n  );\n}\n","src/components/media/AudioLibrary.tsx":"'use client';\n\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate } from '@/lib/format';\nimport { txt } from '@/data/sevas';\nimport { AUDIO, SERIES, clock, seriesName, type AudioTrack, type SeriesKey } from '@/data/media';\n\ntype T = Dictionary['audio'];\nconst SPEEDS = [1, 1.25, 1.5, 2];\n\nconst EQ_CSS = `\n@keyframes eq-bar { 0%,100% { transform: scaleY(.3); } 50% { transform: scaleY(1); } }\n@keyframes disc-turn { to { transform: rotate(360deg); } }\n.eq-bar { transform-origin: bottom; animation: eq-bar 900ms ease-in-out infinite; }\n.disc-turn { animation: disc-turn 14s linear infinite; }\n@media (prefers-reduced-motion: reduce) { .eq-bar, .disc-turn { animation: none; } }\n`;\n\nconst Icon = ({ d, size = 20, fill = false }: { d: string; size?: number; fill?: boolean }) => (\n  <svg width={size} height={size} viewBox=\"0 0 24 24\" fill={fill ? 'currentColor' : 'none'} stroke={fill ? 'none' : 'currentColor'} strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d={d} /></svg>\n);\nconst PLAY = 'M8 5v14l11-7z';\nconst PAUSE = 'M7 5h4v14H7zM13 5h4v14h-4z';\nconst DOWNLOAD = 'M12 4v11M7 11l5 5 5-5M5 20h14';\nconst SHARE = 'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM8.6 13.5l6.8 4M15.4 6.5l-6.8 4';\nconst PREV = 'M6 5v14M20 5L9 12l11 7z';\nconst NEXT = 'M18 5v14M4 5l11 7-11 7z';\n\n// Audio archive: series chips, search and sort, the list of discourses, and a \"Now playing\" panel on the right.\n// Playback uses the real file when `src` is set. Without a file it runs in preview mode (a timer) so the design can be reviewed.\nexport default function AudioLibrary({ t, locale }: { t: T; locale: Locale }) {\n  const [series, setSeries] = useState<'all' | SeriesKey>('all');\n  const [query, setQuery] = useState('');\n  const [sort, setSort] = useState('new');\n  const [picked, setPicked] = useState<Set<string>>(new Set());\n  const [curId, setCurId] = useState<string | null>(null);\n  const [playing, setPlaying] = useState(false);\n  const [time, setTime] = useState(0);\n  const [speed, setSpeed] = useState(1);\n  const [note, setNote] = useState('');\n  const audioRef = useRef<HTMLAudioElement>(null);\n\n  const cur: AudioTrack | null = AUDIO.find((a) => a.id === curId) ?? null;\n\n  const shown = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    const list = AUDIO.filter((a) => (series === 'all' || a.series === series) && (!q || txt(a.title, locale).toLowerCase().includes(q)));\n    if (sort === 'old') return [...list].sort((a, b) => a.date.localeCompare(b.date));\n    if (sort === 'long') return [...list].sort((a, b) => b.duration - a.duration);\n    return [...list].sort((a, b) => b.date.localeCompare(a.date));\n  }, [series, query, sort, locale]);\n\n\n  // Open a shared link (#track-id) on the right track\n  useEffect(() => {\n    const open = () => {\n      const id = window.location.hash.slice(1);\n      if (id && AUDIO.some((a) => a.id === id)) {\n        setCurId(id);\n        setTime(0);\n        setPlaying(false);\n        document.getElementById(`row-${id}`)?.scrollIntoView({ block: 'center' });\n      }\n    };\n    open();\n    window.addEventListener('hashchange', open);\n    return () => window.removeEventListener('hashchange', open);\n  }, []);\n\n  // Say something for a few seconds (copied, nothing to download...)\n  useEffect(() => {\n    if (!note) return;\n    const id = window.setTimeout(() => setNote(''), 4500);\n    return () => window.clearTimeout(id);\n  }, [note]);\n\n  // Preview mode: no file yet, so a timer stands in for the sound\n  useEffect(() => {\n    if (!playing || !cur || cur.src) return;\n    const id = window.setInterval(() => setTime((x) => x + 0.25 * speed), 250);\n    return () => window.clearInterval(id);\n  }, [playing, cur, speed]);\n\n  // Real file: play and pause with the state\n  useEffect(() => {\n    const a = audioRef.current;\n    if (!a || !cur?.src) return;\n    if (playing) a.play().catch(() => setPlaying(false));\n    else a.pause();\n  }, [playing, cur]);\n\n  useEffect(() => {\n    if (audioRef.current) audioRef.current.playbackRate = speed;\n  }, [speed, curId]);\n\n  // Reached the end: go to the next discourse in the list\n  useEffect(() => {\n    if (cur && playing && time >= cur.duration) step(1);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [time]);\n\n  function start(id: string) {\n    if (id === curId) {\n      setPlaying((p) => !p);\n      return;\n    }\n    setCurId(id);\n    setTime(0);\n    setPlaying(true);\n  }\n\n  function step(dir: 1 | -1) {\n    if (shown.length === 0) return;\n    const i = shown.findIndex((a) => a.id === curId);\n    const next = i < 0 ? shown[0] : shown[i + dir];\n    if (!next) {\n      setPlaying(false);\n      setTime(0);\n      return;\n    }\n    setCurId(next.id);\n    setTime(0);\n    setPlaying(true);\n  }\n\n  function seek(v: number) {\n    setTime(v);\n    if (audioRef.current && cur?.src) audioRef.current.currentTime = v;\n  }\n\n  const jump = (d: number) => cur && seek(Math.min(cur.duration, Math.max(0, time + d)));\n\n  async function share(a: AudioTrack) {\n    const url = `${window.location.origin}${window.location.pathname}#${a.id}`;\n    try {\n      await navigator.clipboard.writeText(url);\n      setNote(t.linkCopied);\n    } catch {\n      setNote(url);\n    }\n  }\n\n  function togglePick(id: string) {\n    setPicked((s) => {\n      const n = new Set(s);\n      if (n.has(id)) n.delete(id);\n      else n.add(id);\n      return n;\n    });\n  }\n\n  const allShownPicked = shown.length > 0 && shown.every((a) => picked.has(a.id));\n  const toggleAll = () =>\n    setPicked((s) => {\n      const n = new Set(s);\n      if (allShownPicked) shown.forEach((a) => n.delete(a.id));\n      else shown.forEach((a) => n.add(a.id));\n      return n;\n    });\n\n  // Browsers allow several downloads in a row; a real zip file needs the server (later)\n  function batchDownload() {\n    const files = AUDIO.filter((a) => picked.has(a.id) && a.src);\n    if (files.length === 0) {\n      setNote(t.noFiles);\n      return;\n    }\n    files.forEach((a, i) =>\n      window.setTimeout(() => {\n        const el = document.createElement('a');\n        el.href = a.src;\n        el.download = '';\n        document.body.appendChild(el);\n        el.click();\n        el.remove();\n      }, i * 600),\n    );\n  }\n\n  const iconBtn = 'inline-flex h-9 w-9 items-center justify-center rounded-full text-saffron transition-colors hover:bg-saffron/15 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n  const pct = cur ? Math.min(100, (time / cur.duration) * 100) : 0;\n\n  return (\n    <div className=\"relative\">\n      <style>{EQ_CSS}</style>\n      {cur?.src && (\n        <audio\n          ref={audioRef}\n          src={cur.src}\n          preload=\"metadata\"\n          onTimeUpdate={(e) => setTime(e.currentTarget.currentTime)}\n          onEnded={() => step(1)}\n        />\n      )}\n\n      {/* Series chips */}\n      <div role=\"group\" aria-label={t.filtersLabel} className=\"flex flex-wrap gap-2\">\n        {[{ key: 'all' as const, label: t.all }, ...SERIES.filter((s) => s.key !== 'events').map((s) => ({ key: s.key, label: s.name[locale] }))].map((c) => {\n          const on = series === c.key;\n          return (\n            <button\n              key={c.key}\n              type=\"button\"\n              aria-pressed={on}\n              onClick={() => setSeries(c.key)}\n              className={`rounded-full px-4 py-1.5 text-sm font-semibold ring-1 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${on ? 'bg-saffron text-charcoal ring-saffron' : 'bg-white text-maroon ring-saffron/60 hover:bg-rose'}`}\n            >\n              {c.label}\n            </button>\n          );\n        })}\n      </div>\n\n      <div className=\"mt-8 flex flex-col gap-8 lg:flex-row lg:items-start\">\n        {/* Archive */}\n        <div className=\"min-w-0 flex-1 pb-28 lg:pb-0\">\n          <div className=\"flex flex-wrap items-end justify-between gap-3\">\n            <h2 className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl [html[lang='ta']_&]:sm:text-3xl\">{t.archiveTitle}</h2>\n            <button\n              type=\"button\"\n              onClick={batchDownload}\n              disabled={picked.size === 0}\n              className=\"inline-flex items-center gap-2 rounded-md px-3 py-2 text-sm font-bold text-maroon transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:bg-transparent\"\n            >\n              <Icon d={DOWNLOAD} size={18} /> {t.batchDownload}{picked.size > 0 ? ` (${picked.size})` : ''}\n            </button>\n          </div>\n\n          <div className=\"mt-4 flex flex-col gap-3 sm:flex-row\">\n            <label className=\"block sm:flex-1\">\n              <span className=\"sr-only\">{t.searchLabel}</span>\n              <input type=\"search\" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t.searchPlaceholder} className=\"w-full rounded-md border border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\" />\n            </label>\n            <label className=\"block sm:w-52\">\n              <span className=\"sr-only\">{t.sortLabel}</span>\n              <select value={sort} onChange={(e) => setSort(e.target.value)} className=\"w-full rounded-md border border-rose bg-white px-3 py-2.5 text-charcoal focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\">\n                {t.sortOptions.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}\n              </select>\n            </label>\n          </div>\n\n          <div className=\"mt-4 flex flex-wrap items-center justify-between gap-2 text-sm font-semibold text-charcoal/70\">\n            <label className=\"inline-flex cursor-pointer items-center gap-2\">\n              <input type=\"checkbox\" checked={allShownPicked} onChange={toggleAll} disabled={shown.length === 0} className=\"h-4 w-4 accent-maroon\" />\n              {t.selectAll}\n            </label>\n            <p role=\"status\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n          </div>\n          <p role=\"status\" className=\"min-h-[1.5rem] pt-1 text-sm font-semibold text-maroon\">{note}</p>\n\n          {shown.length > 0 ? (\n            <ul className=\"mt-1 space-y-3\">\n              {shown.map((a) => {\n                const on = a.id === curId;\n                const title = txt(a.title, locale);\n                return (\n                  <li key={a.id} id={`row-${a.id}`} className={`scroll-mt-28 rounded-2xl p-3 transition-shadow sm:p-4 ${on ? 'bg-white shadow-md ring-2 ring-saffron' : 'bg-rose/40 ring-1 ring-rose hover:bg-white hover:shadow-sm'}`}>\n                    <div className=\"flex items-center gap-3 sm:gap-4\">\n                      <input type=\"checkbox\" checked={picked.has(a.id)} onChange={() => togglePick(a.id)} aria-label={t.select.replace('{title}', title)} className=\"h-4 w-4 shrink-0 accent-maroon\" />\n\n                      <button type=\"button\" onClick={() => start(a.id)} aria-label={`${on && playing ? t.pause : t.play}: ${title}`} aria-pressed={on && playing} className=\"relative flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-maroon text-white transition-transform hover:scale-105 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n                        {on && (\n                          <svg aria-hidden=\"true\" viewBox=\"0 0 48 48\" className=\"absolute inset-0 -rotate-90\">\n                            <circle cx=\"24\" cy=\"24\" r=\"22\" fill=\"none\" stroke=\"rgba(255,255,255,.25)\" strokeWidth=\"2.5\" />\n                            <circle cx=\"24\" cy=\"24\" r=\"22\" fill=\"none\" stroke=\"#D97706\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeDasharray={138.2} strokeDashoffset={138.2 - (138.2 * pct) / 100} />\n                          </svg>\n                        )}\n                        <Icon d={on && playing ? PAUSE : PLAY} fill />\n                      </button>\n\n                      <div className=\"min-w-0 flex-1\">\n                        <p className=\"font-display text-lg font-semibold leading-snug text-charcoal sm:text-xl [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-base\">{title}</p>\n                        <p className=\"mt-0.5 flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-charcoal/70\">\n                          <span className=\"rounded-full bg-maroon/10 px-2.5 py-0.5 text-xs font-bold text-maroon\">{seriesName(a.series, locale)}</span>\n                          <span className=\"tabular-nums\">{clock(a.duration)}</span>\n                          <span>{formatDate(a.date, locale)}</span>\n                          {on && playing && (\n                            <span aria-hidden=\"true\" className=\"flex h-4 items-end gap-0.5\">\n                              {[0, 150, 300, 450].map((d) => <span key={d} className=\"eq-bar block h-full w-1 rounded-sm bg-saffron\" style={{ animationDelay: `${d}ms` }} />)}\n                            </span>\n                          )}\n                        </p>\n                      </div>\n\n                      <div className=\"flex shrink-0 items-center\">\n                        {a.src ? (\n                          <a href={a.src} download aria-label={`${t.download}: ${title}`} className={iconBtn}><Icon d={DOWNLOAD} /></a>\n                        ) : (\n                          <button type=\"button\" onClick={() => setNote(t.noFiles)} aria-label={`${t.download}: ${title}`} className={`${iconBtn} opacity-60`}><Icon d={DOWNLOAD} /></button>\n                        )}\n                        <button type=\"button\" onClick={() => share(a)} aria-label={`${t.share}: ${title}`} className={iconBtn}><Icon d={SHARE} /></button>\n                      </div>\n                    </div>\n                  </li>\n                );\n              })}\n            </ul>\n          ) : (\n            <div className=\"mt-4 rounded-2xl bg-rose/50 px-6 py-12 text-center\">\n              <p className=\"font-serif text-lg text-charcoal\">{t.noResults}</p>\n              <button type=\"button\" onClick={() => { setSeries('all'); setQuery(''); }} className=\"mt-4 rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.clearFilters}</button>\n            </div>\n          )}\n        </div>\n\n        {/* Now playing: a card on the right on desktop, a bar at the bottom of the screen on phones */}\n        <aside aria-label={t.nowPlaying} className={`${cur ? 'fixed inset-x-0 bottom-0 z-40' : 'hidden'} lg:static lg:z-auto lg:block lg:w-96 lg:shrink-0`}>\n          <div className=\"lg:sticky lg:top-24\">\n            <div className=\"border-t-2 border-saffron bg-charcoal p-4 text-white shadow-2xl lg:rounded-2xl lg:border-t-0 lg:p-6\">\n              <p className=\"hidden text-xs font-bold uppercase tracking-[0.2em] text-saffron lg:block [html[lang='ta']_&]:tracking-normal\">{t.nowPlaying}</p>\n\n              {/* Disc */}\n              <div aria-hidden=\"true\" className=\"relative mx-auto mt-5 hidden h-52 w-52 items-center justify-center lg:flex\">\n                <div className={`absolute inset-0 rounded-full ${playing ? 'disc-turn' : ''}`} style={{ background: 'conic-gradient(from 0deg, #7A1C1C, #231A18, #7A1C1C, #231A18, #7A1C1C)', boxShadow: '0 0 50px rgba(217,119,6,0.35)' }}>\n                  <div className=\"absolute inset-3 rounded-full border border-white/10\" />\n                  <div className=\"absolute inset-8 rounded-full border border-white/10\" />\n                  <div className=\"absolute inset-14 rounded-full border border-saffron/30\" />\n                </div>\n                <div className=\"relative flex h-20 w-20 items-center justify-center rounded-full bg-saffron text-charcoal\">\n                  <svg width=\"40\" height=\"40\" viewBox=\"0 0 200 200\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"6\">\n                    {[0, 60, 120].map((d) => <ellipse key={d} cx=\"100\" cy=\"100\" rx=\"22\" ry=\"80\" transform={`rotate(${d} 100 100)`} />)}\n                  </svg>\n                </div>\n              </div>\n\n              <div className=\"flex items-center gap-3 lg:mt-5 lg:block\">\n                <div className=\"min-w-0 flex-1 lg:text-center\">\n                  <p className=\"truncate font-display text-lg font-semibold lg:whitespace-normal lg:text-2xl lg:leading-tight [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-base\">{cur ? txt(cur.title, locale) : t.pickOne}</p>\n                  <p className=\"truncate text-sm text-white/70 lg:mt-1\">{cur ? seriesName(cur.series, locale) : t.pickText}</p>\n                </div>\n                <button type=\"button\" onClick={() => cur && setPlaying((p) => !p)} disabled={!cur} aria-label={playing ? t.pause : t.play} className=\"flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-saffron text-charcoal transition-transform hover:scale-105 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:opacity-50 lg:hidden\">\n                  <Icon d={playing ? PAUSE : PLAY} fill />\n                </button>\n              </div>\n\n              <div className=\"mt-3 flex items-center gap-3 text-xs text-white/80 lg:mt-5\">\n                <span className=\"w-11 text-right tabular-nums\">{clock(time)}</span>\n                <input type=\"range\" min={0} max={cur?.duration ?? 1} step={1} value={Math.min(time, cur?.duration ?? 1)} disabled={!cur} aria-label={t.seek} onChange={(e) => seek(Number(e.target.value))} className=\"h-1.5 w-full cursor-pointer accent-[#D97706] disabled:cursor-not-allowed\" />\n                <span className=\"w-11 tabular-nums\">{clock(cur?.duration ?? 0)}</span>\n              </div>\n\n              <div className=\"mt-3 hidden items-center justify-center gap-1 lg:flex\">\n                <button type=\"button\" disabled={!cur} onClick={() => step(-1)} aria-label={t.prev} className={iconBtn}><Icon d={PREV} /></button>\n                <button type=\"button\" disabled={!cur} onClick={() => jump(-15)} aria-label={t.back15} className={`${iconBtn} text-xs font-bold`}>−15</button>\n                <button type=\"button\" disabled={!cur} onClick={() => setPlaying((p) => !p)} aria-label={playing ? t.pause : t.play} className=\"mx-2 flex h-14 w-14 items-center justify-center rounded-full bg-saffron text-charcoal transition-transform hover:scale-105 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:opacity-50\">\n                  <Icon d={playing ? PAUSE : PLAY} size={24} fill />\n                </button>\n                <button type=\"button\" disabled={!cur} onClick={() => jump(15)} aria-label={t.fwd15} className={`${iconBtn} text-xs font-bold`}>+15</button>\n                <button type=\"button\" disabled={!cur} onClick={() => step(1)} aria-label={t.next} className={iconBtn}><Icon d={NEXT} /></button>\n              </div>\n\n              <div className=\"mt-3 hidden items-center justify-between lg:flex\">\n                <button type=\"button\" disabled={!cur} onClick={() => setSpeed(SPEEDS[(SPEEDS.indexOf(speed) + 1) % SPEEDS.length])} aria-label={`${t.speed}: ${speed}x`} className=\"min-w-[3.5rem] rounded border border-white/40 px-2 py-1 text-sm font-semibold hover:bg-white hover:text-charcoal disabled:opacity-50\">{speed}x</button>\n                {cur && !cur.src && <p className=\"ml-3 text-xs leading-snug text-white/60\">{t.demoNote}</p>}\n              </div>\n            </div>\n          </div>\n        </aside>\n      </div>\n\n    </div>\n  );\n}\n","src/components/media/VideoLibrary.tsx":"'use client';\n\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate } from '@/lib/format';\nimport { txt } from '@/data/sevas';\nimport { SERIES, VIDEOS, YOUTUBE_URL, clock, seriesName, type SeriesKey, type VideoItem } from '@/data/media';\n\ntype T = Dictionary['video'];\nconst PAGE = 6;\n\nfunction PlayBadge({ big = false }: { big?: boolean }) {\n  return (\n    <span aria-hidden=\"true\" className={`flex items-center justify-center rounded-full bg-saffron text-charcoal shadow-lg transition-transform group-hover:scale-110 ${big ? 'h-20 w-20' : 'h-14 w-14'}`}>\n      <svg width={big ? 34 : 24} height={big ? 34 : 24} viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M8 5v14l11-7z\" /></svg>\n    </span>\n  );\n}\n\n// Video lectures: a featured lecture, series chips and search, a grid of lectures, and a pop-up player.\nexport default function VideoLibrary({ t, locale }: { t: T; locale: Locale }) {\n  const [series, setSeries] = useState<'all' | SeriesKey>('all');\n  const [query, setQuery] = useState('');\n  const [limit, setLimit] = useState(PAGE);\n  const [open, setOpen] = useState<VideoItem | null>(null);\n  const dialogRef = useRef<HTMLDialogElement>(null);\n  const opener = useRef<HTMLElement | null>(null);\n\n  const featured = VIDEOS.find((v) => v.featured) ?? VIDEOS[0];\n\n  const shown = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return VIDEOS.filter((v) => (series === 'all' || v.series === series) && (!q || txt(v.title, locale).toLowerCase().includes(q))).sort((a, b) => b.date.localeCompare(a.date));\n  }, [series, query, locale]);\n\n  useEffect(() => setLimit(PAGE), [series, query]);\n\n  // The native dialog gives us Esc to close, a focus trap and a dimmed page\n  useEffect(() => {\n    const d = dialogRef.current;\n    if (!d) return;\n    if (open && !d.open) d.showModal();\n    if (!open && d.open) d.close();\n  }, [open]);\n\n  function show(v: VideoItem, e: React.MouseEvent<HTMLElement>) {\n    opener.current = e.currentTarget;\n    setOpen(v);\n  }\n  function close() {\n    setOpen(null);\n    opener.current?.focus();\n  }\n\n  const chips = [{ key: 'all' as const, label: t.all }, ...SERIES.map((s) => ({ key: s.key, label: s.name[locale] }))];\n\n  return (\n    <div>\n      {/* Featured */}\n      <section aria-labelledby=\"featured-title\">\n        <h2 id=\"featured-title\" className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl [html[lang='ta']_&]:sm:text-3xl\">{t.featuredTitle}</h2>\n        <button type=\"button\" onClick={(e) => show(featured, e)} aria-label={`${t.watch}: ${txt(featured.title, locale)}`} className=\"group relative mt-5 block w-full overflow-hidden rounded-2xl bg-charcoal text-left shadow-xl focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-saffron\">\n          <div className=\"aspect-[16/9] w-full bg-cover bg-center transition-transform duration-700 group-hover:scale-105 sm:aspect-[21/9]\" style={{ backgroundImage: `url('${featured.thumb}'), linear-gradient(135deg, #7A1C1C, #231A18)` }} />\n          <div aria-hidden=\"true\" className=\"absolute inset-0 bg-gradient-to-t from-charcoal via-charcoal/40 to-transparent\" />\n          <div className=\"absolute inset-0 flex items-center justify-center\"><PlayBadge big /></div>\n          <div className=\"absolute inset-x-0 bottom-0 p-5 sm:p-8\">\n            <span className=\"rounded-full bg-saffron px-3 py-1 text-xs font-bold text-charcoal\">{seriesName(featured.series, locale)}</span>\n            <p className=\"mt-3 max-w-3xl font-display text-2xl font-semibold leading-tight text-white sm:text-4xl [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-xl [html[lang='ta']_&]:sm:text-3xl\">{txt(featured.title, locale)}</p>\n            <p className=\"mt-2 hidden max-w-2xl text-white/85 sm:block\">{txt(featured.desc, locale)}</p>\n            <p className=\"mt-2 text-sm font-semibold text-white/80\">{clock(featured.duration)} · {formatDate(featured.date, locale)}</p>\n          </div>\n        </button>\n      </section>\n\n      {/* Library */}\n      <section aria-labelledby=\"library-title\" className=\"mt-14\">\n        <h2 id=\"library-title\" className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl [html[lang='ta']_&]:sm:text-3xl\">{t.libraryTitle}</h2>\n\n        <div role=\"group\" aria-label={t.filtersLabel} className=\"mt-5 flex flex-wrap gap-2\">\n          {chips.map((c) => {\n            const on = series === c.key;\n            return (\n              <button key={c.key} type=\"button\" aria-pressed={on} onClick={() => setSeries(c.key)} className={`rounded-full px-4 py-1.5 text-sm font-semibold ring-1 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${on ? 'bg-saffron text-charcoal ring-saffron' : 'bg-white text-maroon ring-saffron/60 hover:bg-rose'}`}>{c.label}</button>\n            );\n          })}\n        </div>\n\n        <div className=\"mt-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between\">\n          <label className=\"block sm:w-96\">\n            <span className=\"sr-only\">{t.searchLabel}</span>\n            <input type=\"search\" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t.searchPlaceholder} className=\"w-full rounded-md border border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\" />\n          </label>\n          <p role=\"status\" className=\"text-sm font-semibold text-charcoal/70\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n        </div>\n\n        {shown.length > 0 ? (\n          <ul className=\"mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n            {shown.slice(0, limit).map((v) => (\n              <li key={v.id}>\n                <button type=\"button\" onClick={(e) => show(v, e)} aria-label={`${t.watch}: ${txt(v.title, locale)}`} className=\"group flex h-full w-full flex-col overflow-hidden rounded-xl bg-white text-left shadow-sm ring-1 ring-rose transition-shadow hover:shadow-lg focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n                  <span className=\"relative block aspect-video w-full overflow-hidden bg-maroon\">\n                    <span className=\"absolute inset-0 bg-cover bg-center transition-transform duration-500 group-hover:scale-105\" style={{ backgroundImage: `url('${v.thumb}'), linear-gradient(135deg, #7A1C1C, #231A18)` }} />\n                    <span aria-hidden=\"true\" className=\"absolute inset-0 bg-charcoal/20 transition-colors group-hover:bg-charcoal/40\" />\n                    <span className=\"absolute inset-0 flex items-center justify-center\"><PlayBadge /></span>\n                    <span className=\"absolute bottom-2 right-2 rounded bg-charcoal/85 px-2 py-0.5 text-xs font-bold tabular-nums text-white\">{clock(v.duration)}</span>\n                  </span>\n                  <span className=\"flex flex-1 flex-col p-4\">\n                    <span className=\"self-start rounded-full bg-rose px-2.5 py-0.5 text-xs font-bold text-maroon\">{seriesName(v.series, locale)}</span>\n                    <span className=\"mt-2 font-display text-xl font-semibold leading-snug text-charcoal [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-lg\">{txt(v.title, locale)}</span>\n                    <span className=\"mt-1 text-sm text-charcoal/75\">{txt(v.desc, locale)}</span>\n                    <span className=\"mt-auto pt-3 text-xs font-semibold text-charcoal/60\">{formatDate(v.date, locale)}</span>\n                  </span>\n                </button>\n              </li>\n            ))}\n          </ul>\n        ) : (\n          <div className=\"mt-6 rounded-2xl bg-rose/50 px-6 py-12 text-center\">\n            <p className=\"font-serif text-lg text-charcoal\">{t.noResults}</p>\n            <button type=\"button\" onClick={() => { setSeries('all'); setQuery(''); }} className=\"mt-4 rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.clearFilters}</button>\n          </div>\n        )}\n\n        {shown.length > limit && (\n          <p className=\"mt-8 text-center\">\n            <button type=\"button\" onClick={() => setLimit((n) => n + PAGE)} className=\"rounded-md border-2 border-maroon px-7 py-3 font-semibold text-maroon hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.loadMore}</button>\n          </p>\n        )}\n      </section>\n\n      {/* YouTube band */}\n      <section className=\"mt-14 rounded-2xl bg-saffron px-6 py-8 text-center text-charcoal sm:px-10 lg:flex lg:items-center lg:justify-between lg:text-left\">\n        <div className=\"max-w-2xl\">\n          <h2 className=\"font-display text-3xl font-semibold !text-charcoal\">{t.youtubeTitle}</h2>\n          <p className=\"mt-2 text-lg\">{t.youtubeText}</p>\n        </div>\n        <a href={YOUTUBE_URL} target=\"_blank\" rel=\"noopener noreferrer\" className=\"mt-5 inline-block rounded-md bg-charcoal px-7 py-3 font-semibold text-white transition-colors hover:bg-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-charcoal lg:mt-0\">\n          {t.youtubeCta}<span className=\"sr-only\"> ({t.newTab})</span>\n        </a>\n      </section>\n\n      {/* Pop-up player */}\n      <dialog ref={dialogRef} onClose={() => setOpen(null)} onClick={(e) => { if (e.target === dialogRef.current) close(); }} aria-label={open ? txt(open.title, locale) : t.watch} className=\"m-auto w-[min(60rem,94vw)] rounded-2xl bg-charcoal p-0 text-white backdrop:bg-charcoal/80\">\n        {open && (\n          <div>\n            <div className=\"relative aspect-video w-full bg-black\">\n              {open.youtubeId ? (\n                <iframe src={`https://www.youtube-nocookie.com/embed/${open.youtubeId}?autoplay=1&rel=0`} title={txt(open.title, locale)} allow=\"autoplay; encrypted-media; picture-in-picture\" allowFullScreen className=\"absolute inset-0 h-full w-full\" />\n              ) : (\n                <div className=\"absolute inset-0 flex flex-col items-center justify-center bg-cover bg-center p-6 text-center\" style={{ backgroundImage: `linear-gradient(rgba(35,26,24,.8), rgba(35,26,24,.8)), url('${open.thumb}')` }}>\n                  <p className=\"font-display text-3xl font-semibold text-white\">{t.comingSoon}</p>\n                  <p className=\"mt-2 max-w-md text-white/80\">{t.comingSoonText}</p>\n                </div>\n              )}\n            </div>\n            <div className=\"flex items-start justify-between gap-4 p-5\">\n              <div>\n                <p className=\"font-display text-2xl font-semibold leading-snug text-white [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">{txt(open.title, locale)}</p>\n                <p className=\"mt-1 text-sm text-white/75\">{seriesName(open.series, locale)} · {clock(open.duration)} · {formatDate(open.date, locale)}</p>\n              </div>\n              <button type=\"button\" onClick={close} className=\"shrink-0 rounded-md border border-white/40 px-4 py-2 text-sm font-semibold hover:bg-white hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.close}</button>\n            </div>\n          </div>\n        )}\n      </dialog>\n    </div>\n  );\n}\n","src/components/media/AlbumGallery.tsx":"'use client';\n\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport Image from 'next/image';\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { txt } from '@/data/sevas';\nimport { ALBUMS, PHOTOS, PHOTO_FOLDER_URL, type AlbumKey } from '@/data/media';\n\ntype T = Dictionary['albums'];\n\n// Photo albums: album chips, a masonry gallery, and a full-screen viewer with previous / next and download.\nexport default function AlbumGallery({ t, locale }: { t: T; locale: Locale }) {\n  const [album, setAlbum] = useState<'all' | AlbumKey>('all');\n  const [index, setIndex] = useState<number | null>(null);\n  const dialogRef = useRef<HTMLDialogElement>(null);\n  const opener = useRef<HTMLElement | null>(null);\n\n  const shown = useMemo(() => PHOTOS.filter((p) => album === 'all' || p.album === album), [album]);\n  const photo = index !== null ? shown[index] : null;\n\n  useEffect(() => {\n    const d = dialogRef.current;\n    if (!d) return;\n    if (index !== null && !d.open) d.showModal();\n    if (index === null && d.open) d.close();\n  }, [index]);\n\n  const go = (dir: 1 | -1) => setIndex((i) => (i === null ? i : (i + dir + shown.length) % shown.length));\n\n  function onKey(e: React.KeyboardEvent) {\n    if (e.key === 'ArrowRight') go(1);\n    if (e.key === 'ArrowLeft') go(-1);\n  }\n  function close() {\n    setIndex(null);\n    opener.current?.focus();\n  }\n\n  const chips = [{ key: 'all' as const, label: t.all }, ...ALBUMS.map((a) => ({ key: a.key, label: a.name[locale] }))];\n  const albumLabel = (k: AlbumKey) => ALBUMS.find((a) => a.key === k)?.name[locale] ?? '';\n\n  return (\n    <div>\n      <div role=\"group\" aria-label={t.filtersLabel} className=\"flex flex-wrap items-center gap-2\">\n        {chips.map((c) => {\n          const on = album === c.key;\n          return (\n            <button key={c.key} type=\"button\" aria-pressed={on} onClick={() => setAlbum(c.key)} className={`rounded-full px-4 py-1.5 text-sm font-semibold ring-1 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${on ? 'bg-saffron text-charcoal ring-saffron' : 'bg-white text-maroon ring-saffron/60 hover:bg-rose'}`}>{c.label}</button>\n          );\n        })}\n        <p role=\"status\" className=\"ml-auto text-sm font-semibold text-charcoal/70\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n      </div>\n\n      <ul className=\"mt-6 columns-1 gap-5 sm:columns-2 lg:columns-3 xl:columns-4\">\n        {shown.map((p, i) => (\n          <li key={p.id} className=\"mb-5 break-inside-avoid\">\n            <figure className=\"group overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-rose transition-shadow hover:shadow-lg\">\n              <button\n                type=\"button\"\n                onClick={(e) => { opener.current = e.currentTarget; setIndex(i); }}\n                aria-label={`${t.open}: ${txt(p.title, locale)}`}\n                className=\"relative block w-full overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-3px] focus-visible:outline-saffron\"\n              >\n                <Image src={p.src} alt={txt(p.title, locale)} width={p.w} height={p.h} sizes=\"(min-width: 1280px) 20rem, (min-width: 1024px) 25vw, (min-width: 640px) 45vw, 92vw\" className=\"h-auto w-full transition-transform duration-500 group-hover:scale-105\" />\n                <span aria-hidden=\"true\" className=\"absolute inset-0 bg-gradient-to-t from-charcoal/60 via-transparent to-transparent opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100\" />\n              </button>\n              <figcaption className=\"flex items-center justify-between gap-3 px-3 py-2.5\">\n                <span className=\"min-w-0\">\n                  <span className=\"block truncate text-sm font-bold text-charcoal\">{txt(p.title, locale)}</span>\n                  <span className=\"block truncate text-xs text-charcoal/60\">{albumLabel(p.album)}</span>\n                </span>\n                <a href={p.src} download aria-label={`${t.download}: ${txt(p.title, locale)}`} className=\"inline-flex shrink-0 items-center gap-1 rounded px-1.5 py-1 text-xs font-bold text-maroon hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">\n                  <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 4v11M7 11l5 5 5-5M5 20h14\" /></svg>\n                  JPG\n                </a>\n              </figcaption>\n            </figure>\n          </li>\n        ))}\n      </ul>\n\n      {/* High-resolution photos */}\n      <section aria-labelledby=\"hires-title\" className=\"mt-14 rounded-2xl bg-maroon px-6 py-8 text-white sm:px-10 lg:flex lg:items-center lg:justify-between\">\n        <div className=\"max-w-2xl\">\n          <h2 id=\"hires-title\" className=\"font-display text-3xl font-semibold !text-white\">{t.hiresTitle}</h2>\n          <p className=\"mt-2 text-lg text-white/90\">{t.hiresText}</p>\n        </div>\n        <div className=\"mt-5 flex flex-col gap-3 sm:flex-row lg:mt-0\">\n          <a href={PHOTO_FOLDER_URL} target=\"_blank\" rel=\"noopener noreferrer\" className=\"rounded-md bg-saffron px-7 py-3 text-center font-semibold text-charcoal transition-colors hover:bg-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">\n            {t.hiresCta}<span className=\"sr-only\"> ({t.newTab})</span>\n          </a>\n          <Link href={`/${locale}/contact`} className=\"rounded-md border-2 border-white/70 px-7 py-3 text-center font-semibold text-white transition-colors hover:bg-white hover:text-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">{t.contactCta}</Link>\n        </div>\n      </section>\n\n      {/* Viewer */}\n      <dialog ref={dialogRef} onClose={() => setIndex(null)} onKeyDown={onKey} onClick={(e) => { if (e.target === dialogRef.current) close(); }} aria-label={photo ? txt(photo.title, locale) : t.open} className=\"m-auto max-h-[94vh] w-[min(72rem,96vw)] overflow-hidden rounded-2xl bg-charcoal p-0 text-white backdrop:bg-charcoal/90\">\n        {photo && (\n          <div className=\"flex max-h-[94vh] flex-col\">\n            <div className=\"relative flex min-h-0 flex-1 items-center justify-center bg-black\">\n              <Image src={photo.src} alt={txt(photo.title, locale)} width={photo.w} height={photo.h} sizes=\"96vw\" priority className=\"max-h-[72vh] w-auto max-w-full object-contain\" />\n              <button type=\"button\" onClick={() => go(-1)} aria-label={t.prev} className=\"absolute left-2 top-1/2 flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-charcoal/70 text-xl hover:bg-saffron hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-white\">‹</button>\n              <button type=\"button\" onClick={() => go(1)} aria-label={t.next} className=\"absolute right-2 top-1/2 flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-charcoal/70 text-xl hover:bg-saffron hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-white\">›</button>\n            </div>\n            <div className=\"flex flex-wrap items-center justify-between gap-3 p-4\">\n              <div>\n                <p className=\"font-display text-xl font-semibold text-white\">{txt(photo.title, locale)}</p>\n                <p className=\"text-sm text-white/70\">{albumLabel(photo.album)} · {t.counter.replace('{i}', String((index ?? 0) + 1)).replace('{n}', String(shown.length))}</p>\n              </div>\n              <div className=\"flex gap-2\">\n                <a href={photo.src} download className=\"rounded-md bg-saffron px-4 py-2 text-sm font-bold text-charcoal hover:bg-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-white\">{t.download}</a>\n                <button type=\"button\" onClick={close} className=\"rounded-md border border-white/40 px-4 py-2 text-sm font-semibold hover:bg-white hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">{t.close}</button>\n              </div>\n            </div>\n          </div>\n        )}\n      </dialog>\n    </div>\n  );\n}\n","src/app/[locale]/audio/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport AudioLibrary from '@/components/media/AudioLibrary';\nimport MediaHero from '@/components/media/MediaHero';\nimport { AUDIO, SERIES } from '@/data/media';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.audio.meta.title} | ${t.site.name}`, description: t.audio.meta.description };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.audio;\n  const hours = Math.round((AUDIO.reduce((s, a) => s + a.duration, 0) / 3600) * 10) / 10;\n  const stats = [\n    { value: String(AUDIO.length), label: t.statItems },\n    { value: String(hours), label: t.statHours },\n    { value: String(SERIES.filter((s) => s.key !== 'events').length), label: t.statSeries },\n  ];\n\n  return (\n    <main>\n      <MediaHero\n        kind=\"audio\"\n        home={dict.nav.home}\n        homeHref={`/${locale}`}\n        current={dict.nav.audio}\n        crumbLabel={t.crumbLabel}\n        eyebrow={t.eyebrow}\n        title={t.title}\n        intro={t.intro}\n        stats={stats}\n      />\n      <section aria-label={t.title} className=\"bg-white pb-16 pt-6 sm:pb-20\">\n        <div className=\"mx-auto max-w-7xl px-4 lg:px-8\">\n          <AudioLibrary t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/video/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport VideoLibrary from '@/components/media/VideoLibrary';\nimport MediaHero from '@/components/media/MediaHero';\nimport { SERIES, VIDEOS } from '@/data/media';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.video.meta.title} | ${t.site.name}`, description: t.video.meta.description };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.video;\n  const hours = Math.round((VIDEOS.reduce((s, v) => s + v.duration, 0) / 3600) * 10) / 10;\n  const stats = [\n    { value: String(VIDEOS.length), label: t.statItems },\n    { value: String(hours), label: t.statHours },\n    { value: String(SERIES.length), label: t.statSeries },\n  ];\n\n  return (\n    <main>\n      <MediaHero\n        kind=\"video\"\n        home={dict.nav.home}\n        homeHref={`/${locale}`}\n        current={dict.nav.video}\n        crumbLabel={t.crumbLabel}\n        eyebrow={t.eyebrow}\n        title={t.title}\n        intro={t.intro}\n        stats={stats}\n      />\n      <section aria-label={t.title} className=\"bg-white pb-16 pt-6 sm:pb-20\">\n        <div className=\"mx-auto max-w-7xl px-4 lg:px-8\">\n          <VideoLibrary t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/albums/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport AlbumGallery from '@/components/media/AlbumGallery';\nimport MediaHero from '@/components/media/MediaHero';\nimport { ALBUMS, PHOTOS } from '@/data/media';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.albums.meta.title} | ${t.site.name}`, description: t.albums.meta.description };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.albums;\n  const stats = [\n    { value: String(PHOTOS.length), label: t.statItems },\n    { value: String(ALBUMS.length), label: t.statAlbums },\n    { value: 'JPG', label: t.statFormat },\n  ];\n\n  return (\n    <main>\n      <MediaHero\n        kind=\"album\"\n        home={dict.nav.home}\n        homeHref={`/${locale}`}\n        current={dict.nav.albums}\n        crumbLabel={t.crumbLabel}\n        eyebrow={t.eyebrow}\n        title={t.title}\n        intro={t.intro}\n        stats={stats}\n      />\n      <section aria-label={t.title} className=\"bg-white pb-16 pt-6 sm:pb-20\">\n        <div className=\"mx-auto max-w-7xl px-4 lg:px-8\">\n          <AlbumGallery t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n"};
